-- Explicit administrator-only rollback of plan fields. Test against a restored backup first.
-- Never deletes records/files or restores stale personal booking/check values.
begin;
select pg_advisory_xact_lock(hashtextextended('20261222-2026-4222-8222-202612270002:plan',0));
do $$ begin if not exists(select 1 from public.plan_revision_backups where trip_id='20261222-2026-4222-8222-202612270002' and plan_version='2026-10-06-r3' and jsonb_array_length(snapshot->'schedule_items')>0) then raise exception 'A populated pre-renewal snapshot is required'; end if; end $$;
update public.places set archived=true where trip_id='20261222-2026-4222-8222-202612270002' and plan_key is not null;
update public.schedule_items set archived=true where trip_id='20261222-2026-4222-8222-202612270002' and plan_key is not null;
update public.transport_segments set archived=true where trip_id='20261222-2026-4222-8222-202612270002' and plan_key is not null;
update public.packing_items set archived=true where trip_id='20261222-2026-4222-8222-202612270002' and plan_key is not null;
update public.checklist_items set archived=true where trip_id='20261222-2026-4222-8222-202612270002' and plan_key is not null;
update public.schedule_places set archived=true where trip_id='20261222-2026-4222-8222-202612270002';
update public.trip_days target set date=original.date,day_number=original.day_number,title=original.title,hotel_name=original.hotel_name,estimated_cost_min_yen=original.estimated_cost_min_yen,estimated_cost_max_yen=original.estimated_cost_max_yen from public.plan_revision_backups b, lateral jsonb_populate_recordset(null::public.trip_days,b.snapshot->'trip_days') original where b.trip_id='20261222-2026-4222-8222-202612270002' and b.plan_version='2026-10-06-r3' and target.trip_id=b.trip_id and target.id=original.id;
update public.places target set custom_name=original.custom_name,category=original.category,memo=original.memo,maps_url=original.maps_url,verified_on=original.verified_on,plan_key=original.plan_key,archived=original.archived from public.plan_revision_backups b, lateral jsonb_populate_recordset(null::public.places,b.snapshot->'places') original where b.trip_id='20261222-2026-4222-8222-202612270002' and b.plan_version='2026-10-06-r3' and target.trip_id=b.trip_id and target.id=original.id;
update public.schedule_items target set date=original.date,type=original.type,title=original.title,time_label=original.time_label,start_time=original.start_time,end_time=original.end_time,place_id=original.place_id,description=original.description,sort_order=original.sort_order,is_fixed=original.is_fixed,estimated_cost_yen=original.estimated_cost_yen,plan_key=original.plan_key,archived=original.archived from public.plan_revision_backups b, lateral jsonb_populate_recordset(null::public.schedule_items,b.snapshot->'schedule_items') original where b.trip_id='20261222-2026-4222-8222-202612270002' and b.plan_version='2026-10-06-r3' and target.trip_id=b.trip_id and target.id=original.id;
update public.transport_segments target set date=original.date,schedule_item_id=original.schedule_item_id,origin_place_id=original.origin_place_id,destination_place_id=original.destination_place_id,origin_name=original.origin_name,destination_name=original.destination_name,departure_time=original.departure_time,arrival_time=original.arrival_time,time_label=original.time_label,transport_type=original.transport_type,route_name=original.route_name,estimated_duration_minutes=original.estimated_duration_minutes,estimated_cost_min_yen=original.estimated_cost_min_yen,estimated_cost_max_yen=original.estimated_cost_max_yen,reservation_required=original.reservation_required,preparation_note=original.preparation_note,is_fixed=original.is_fixed,plan_key=original.plan_key,archived=original.archived from public.plan_revision_backups b, lateral jsonb_populate_recordset(null::public.transport_segments,b.snapshot->'transport_segments') original where b.trip_id='20261222-2026-4222-8222-202612270002' and b.plan_version='2026-10-06-r3' and target.trip_id=b.trip_id and target.id=original.id;
update public.schedule_places target set sort_order=original.sort_order,archived=original.archived from public.plan_revision_backups b, lateral jsonb_populate_recordset(null::public.schedule_places,b.snapshot->'schedule_places') original where b.trip_id='20261222-2026-4222-8222-202612270002' and b.plan_version='2026-10-06-r3' and target.trip_id=b.trip_id and target.id=original.id;
update public.reservations target set archived=original.archived from public.plan_revision_backups b,lateral jsonb_populate_recordset(null::public.reservations,b.snapshot->'reservations') original where b.trip_id='20261222-2026-4222-8222-202612270002' and b.plan_version='2026-10-06-r3' and target.trip_id=b.trip_id and target.id=original.id;
update public.packing_items target set archived=original.archived from public.plan_revision_backups b,lateral jsonb_populate_recordset(null::public.packing_items,b.snapshot->'packing_items') original where b.trip_id='20261222-2026-4222-8222-202612270002' and b.plan_version='2026-10-06-r3' and target.trip_id=b.trip_id and target.id=original.id;
update public.checklist_items target set archived=original.archived from public.plan_revision_backups b,lateral jsonb_populate_recordset(null::public.checklist_items,b.snapshot->'checklist_items') original where b.trip_id='20261222-2026-4222-8222-202612270002' and b.plan_version='2026-10-06-r3' and target.trip_id=b.trip_id and target.id=original.id;
update public.trips target set plan_version=original.plan_version from public.plan_revision_backups b,lateral jsonb_populate_recordset(null::public.trips,b.snapshot->'trips') original where b.trip_id=target.id and b.plan_version='2026-10-06-r3';
commit;
